.option--incorrect .option__label {
  border-color: var(--color-incorrect-border);
  background: var(--color-incorrect-bg);
}

.option--incorrect .option__label .option__box {
  background: var(--color-incorrect);
  border-color: var(--color-incorrect);
}

.option--incorrect .option__label .option__checkmark {
  display: block;
}

.option--missed .option__label {
  border-color: var(--color-missed-border);
  background: var(--color-missed-bg);
}

.option--missed .option__label .option__box {
  border-color: var(--color-missed);
  background: var(--color-missed-bg);
}

.option__badge {
  display: none;
  font-size: .72rem;
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 999px;
}

.option--correct .option__badge {
  display: inline-flex;
  background: #dcfce7;
  color: var(--color-correct);
}

.option--incorrect .option__badge {
  display: inline-flex;
  background: #fee2e2;
  color: var(--color-incorrect);
}

.option--missed .option__badge {
  display: inline-flex;
  background: #fef3c7;
  color: var(--color-missed);
