/* disable interaction after submit */
.quiz-form--submitted .option__label {
  cursor: default;
  pointer-events: none;
}

/* ── Submit area ── */
.quiz-actions {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 14px;
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  background: var(--color-primary);
  color: #fff;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background .15s, box-shadow .15s, transform .1s;
  box-shadow: 0 2px 8px rgba(79,110,247,.35);
}

.btn-submit:hover {
  background: var(--color-primary-hover);
}

.btn-submit:active {
  background: var(--color-primary-active);
  transform: translateY(1px);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

.btn-submit:disabled {
  opacity: .65;
  cursor: not-allowed;
  box-shadow: none;
}

.btn-retry {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 28px;
  background: transparent;
  color: var(--color-primary);
  font-family: var(--font);
  font-size: .95rem;
  font-weight: 600;
  border: 1.5px solid var(--color-primary);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background .15s;
}

.btn-retry:hover {
  background: var(--color-result-bg);
}

.btn-retry:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* ── Score banner ── */
.score-banner {
  background: var(--color-surface);
  border: 1px solid var(--color-result-border);
  border-radius: var(--radius-lg);
  padding: 24px 28px;
  box-shadow: var(--shadow-card);
  display: none;
  flex-direction: column;
  gap: 6px;
}

.score-banner[aria-hidden="false"] {
  display: flex;
}

.score-banner__heading {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--color-text);
}

.score-banner__body {
  font-size: .9rem;
  color: var(--color-text-muted);
}

.score-banner__bar-wrap {
  margin-top: 10px;
  height: 8px;
  background: var(--color-bg);
  border-radius: 999px;
  overflow: hidden;
}

.score-banner__bar {
  height: 100%;
  background: var(--color-primary);
  border-radius: 999px;
  transition: width .5s ease;
}

/* ── Live region for AT announcements ── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Responsive ── */
@media (max-width: 480px) {
  .form-field {
    padding: 20px 18px;
  }

  .option__label {
    padding: 11px 13px;
  }
}
