*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-bg: #f5f6fa;
  --color-surface: #ffffff;
  --color-border: #e2e5ee;
  --color-border-focus: #4f6ef7;
  --color-primary: #4f6ef7;
  --color-primary-hover: #3a58e0;
  --color-primary-active: #2f49cc;
  --color-text: #1a1d2e;
  --color-text-muted: #6b7280;
  --color-help: #5c6680;
  --color-check-bg: #4f6ef7;
  --color-check-border: #c5cade;
  --color-correct: #16a34a;
  --color-correct-bg: #f0fdf4;
  --color-correct-border: #86efac;
  --color-incorrect: #dc2626;
  --color-incorrect-bg: #fef2f2;
  --color-incorrect-border: #fca5a5;
  --color-missed: #d97706;
  --color-missed-bg: #fffbeb;
  --color-missed-border: #fcd34d;
  --color-result-bg: #eef1ff;
  --color-result-border: #c7d0f8;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-card: 0 1px 4px rgba(0,0,0,.06), 0 4px 20px rgba(0,0,0,.07);
  --font: 'Inter', system-ui, -apple-system, sans-serif;
}

body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  padding: 40px 16px 80px;
  line-height: 1.5;
}

/* ── Page header ── */
.page-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 36px;
}

.page-header__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-primary);
  background: var(--color-result-bg);
  border: 1px solid var(--color-result-border);
  border-radius: 999px;
  padding: 4px 12px;
  margin-bottom: 16px;
}

.page-header__title {
  font-size: clamp(1.6rem, 5vw, 2.25rem);
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-text);
  margin-bottom: 10px;
}

.page-header__subtitle {
  font-size: .95rem;
  color: var(--color-text-muted);
}

/* ── Quiz form ── */
.quiz-form {
  max-width: 640px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ── Question card (form-field) ── */
.form-field {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 28px;
  box-shadow: var(--shadow-card);
  transition: border-color .15s;
}

.form-field:focus-within {
  border-color: var(--color-border-focus);
}

.form-field__meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
}

.form-field__number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--color-primary);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  flex-shrink: 0;
}

.form-field__label {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--color-text);
  flex: 1;
}

.form-field__select-hint {
  font-size: .78rem;
  font-weight: 500;
  color: var(--color-text-muted);
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 999px;
  padding: 2px 9px;
  white-space: nowrap;
}

.form-field__help {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  background: var(--color-result-bg);
  border: 1px solid var(--color-result-border);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  margin-bottom: 18px;
  font-size: .85rem;
  color: var(--color-help);
  line-height: 1.5;
}

.form-field__help svg {
  flex-shrink: 0;
  margin-top: 1px;
  color: var(--color-primary);
}

/* ── Checkbox option ── */
.options-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  list-style: none;
}

.option {
  position: relative;
}

.option__input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.option__label {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 13px 16px;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  font-size: .95rem;
  transition: border-color .12s, background .12s, box-shadow .12s;
  user-select: none;
}

.option__label:hover {
  border-color: var(--color-border-focus);
  background: #f7f8ff;
}

.option__input:focus-visible + .option__label {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* Custom checkbox box */
.option__box {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border: 2px solid var(--color-check-border);
  border-radius: 5px;
  flex-shrink: 0;
  background: #fff;
  transition: border-color .12s, background .12s;
}

.option__input:checked + .option__label {
  border-color: var(--color-primary);
  background: #f4f6ff;
}

.option__input:checked + .option__label .option__box {
  background: var(--color-primary);
  border-color: var(--color-primary);
}

.option__checkmark {
  display: none;
  width: 11px;
  height: 11px;
  fill: none;
  stroke: #fff;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.option__input:checked + .option__label .option__checkmark {
  display: block;
}

.option__text {
  flex: 1;
  color: var(--color-text);
}

/* ── Result states (applied after submit) ── */
.option--correct .option__label {
  border-color: var(--color-correct-border);
  background: var(--color-correct-bg);
}

.option--correct .option__label .option__box {
  background: var(--color-correct);
  border-color: var(--color-correct);
}

.option--correct .option__input:checked + .option__label .option__checkmark,
.option--correct .option__label .option__checkmark {
  display: block;
  stroke: #fff;
}

.option--incorrect .option__label {
  border-color: var(--color-incorrect-border);
  background: var(--color-incorrect-bg);
}

.option--incorrect .option__label .option__box {
  background: var(--color-incorrect);
  border-color: var(--color-incorrect);
}

.option--incorrect .option__label .option__checkmark {
  display: block;
}

.option--missed .option__label {
  border-color: var(--color-missed-border);
  background: var(--color-missed-bg);
}

.option--missed .option__label .option__box {
  border-color: var(--color-missed);
  background: var(--color-missed-bg);
}

.option__badge {
  display: none;
  font-size: .72rem;
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 999px;
}

.option--correct .option__badge {
  display: inline-flex;
  background: #dcfce7;
  color: var(--color-correct);
}

.option--incorrect .option__badge {
  display: inline-flex;
  background: #fee2e2;
  color: var(--color-incorrect);
}

.option--missed .option__badge {
  display: inline-flex;
  background: #fef3c7;
  color: var(--color-missed);
}

/* disable interaction after submit */
.quiz-form--submitted .option__label {
  cursor: default;
  pointer-events: none;
}

/* ── Submit area ── */
.quiz-actions {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 14px;
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  background: var(--color-primary);
  color: #fff;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background .15s, box-shadow .15s, transform .1s;
  box-shadow: 0 2px 8px rgba(79,110,247,.35);
}

.btn-submit:hover {
  background: var(--color-primary-hover);
}

.btn-submit:active {
  background: var(--color-primary-active);
  transform: translateY(1px);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

.btn-submit:disabled {
  opacity: .65;
  cursor: not-allowed;
  box-shadow: none;
}

.btn-retry {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 28px;
  background: transparent;
  color: var(--color-primary);
  font-family: var(--font);
  font-size: .95rem;
  font-weight: 600;
  border: 1.5px solid var(--color-primary);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background .15s;
}

.btn-retry:hover {
  background: var(--color-result-bg);
}

.btn-retry:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* ── Score banner ── */
.score-banner {
  background: var(--color-surface);
  border: 1px solid var(--color-result-border);
  border-radius: var(--radius-lg);
  padding: 24px 28px;
  box-shadow: var(--shadow-card);
  display: none;
  flex-direction: column;
  gap: 6px;
}

.score-banner[aria-hidden="false"] {
  display: flex;
}

.score-banner__heading {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--color-text);
}

.score-banner__body {
  font-size: .9rem;
  color: var(--color-text-muted);
}

.score-banner__bar-wrap {
  margin-top: 10px;
  height: 8px;
  background: var(--color-bg);
  border-radius: 999px;
  overflow: hidden;
}

.score-banner__bar {
  height: 100%;
  background: var(--color-primary);
  border-radius: 999px;
  transition: width .5s ease;
}

/* ── Live region for AT announcements ── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Responsive ── */
@media (max-width: 480px) {
  .form-field {
    padding: 20px 18px;
  }

  .option__label {
    padding: 11px 13px;
  }
}

/**
 * Computer Languages Quiz
 *
 * Component-style architecture:
 *   QuizApp        – root controller
 *     QuestionCard – renders one question + its options
 *       OptionItem – renders a single checkbox option
 *     ScoreBanner  – shows result after submission
 */

// ── Data ──────────────────────────────────────────────────────────────────────

const QUESTIONS = [
  {
    id: "q1",
