  const fieldset = el("fieldset", { className: "form-field", id: `field-${question.id}` });

  // Meta row: number badge + legend + hint pill
  const legend = document.createElement("legend");
  legend.className = "form-field__meta";

  const numBadge = el("span", { className: "form-field__number", ariaHidden: "true" },
    String(question.number)
  );
  const labelText = el("span", { className: "form-field__label" }, question.text);
  const hint = el("span", { className: "form-field__select-hint" }, "Select all that apply");

  legend.appendChild(numBadge);
  legend.appendChild(labelText);
  legend.appendChild(hint);
  fieldset.appendChild(legend);

  // Optional help text
  if (question.help) {
    const helpId = `help-${question.id}`;
    const helpDiv = el("div", { className: "form-field__help", id: helpId, role: "note" });
    helpDiv.appendChild(InfoIcon());
    helpDiv.appendChild(el("span", {}, question.help));
    fieldset.appendChild(helpDiv);
    fieldset.setAttribute("aria-describedby", helpId);
  }

  // Options list
  const list = el("ul", { className: "options-list", role: "group" });
  const optionRefs = [];

  for (const option of question.options) {
    const { wrapper, input, badge } = OptionItem({
      questionId: question.id,
      option,
      name: question.id,
    });
    list.appendChild(wrapper);
    optionRefs.push({ option, wrapper, input, badge });
  }

  fieldset.appendChild(list);

  /** Return selected option IDs */
  function getSelected() {
    return optionRefs.filter((r) => r.input.checked).map((r) => r.option.id);
  }

  /** Apply result styling after submit */
  function applyResults() {
    const selected = new Set(getSelected());
    const correct = new Set(question.correctIds);

    for (const { option, wrapper, input, badge } of optionRefs) {
      const isSelected = selected.has(option.id);
      const isCorrect = correct.has(option.id);

      input.disabled = true;

      if (isSelected && isCorrect) {
        wrapper.classList.add("option--correct");
        badge.textContent = "Correct ✓";
      } else if (isSelected && !isCorrect) {
        wrapper.classList.add("option--incorrect");
        badge.textContent = "Incorrect ✗";
      } else if (!isSelected && isCorrect) {
        wrapper.classList.add("option--missed");
        badge.textContent = "Missed";
      }
    }
  }

  /** Count correctly answered options for this question */
  function score() {
    const selected = new Set(getSelected());
    const correct = new Set(question.correctIds);
    // A question is "fully correct" when selected == correct
    return selected.size === correct.size &&
      [...selected].every((id) => correct.has(id))
      ? 1
      : 0;
  }

  return { fieldset, getSelected, applyResults, score };
}

// ── ScoreBanner component ─────────────────────────────────────────────────────

function ScoreBanner() {
  const banner = el("div", {
    className: "score-banner",
    role: "status",
    ariaLive: "polite",
    ariaAtomic: "true",
    ariaHidden: "true",
    id: "score-banner",
  });

  const heading = el("p", { className: "score-banner__heading" });
  const body = el("p", { className: "score-banner__body" });
  const barWrap = el("div", { className: "score-banner__bar-wrap", ariaHidden: "true" });
  const bar = el("div", { className: "score-banner__bar" });
  bar.style.width = "0%";
  barWrap.appendChild(bar);

  banner.appendChild(heading);
  banner.appendChild(body);
  banner.appendChild(barWrap);

  function show(correct, total) {
    const pct = Math.round((correct / total) * 100);
    heading.textContent =
      correct === total
        ? `🎉 Perfect score! You got all ${total} questions right.`
        : `You scored ${correct} out of ${total}.`;
    body.textContent =
      correct === total
        ? "Excellent work — you know your computer languages!"
        : "Review the highlighted answers below to see what you missed.";
    bar.style.width = pct + "%";
    banner.setAttribute("aria-hidden", "false");
  }

  return { banner, show };
}

// ── QuizApp (root) ────────────────────────────────────────────────────────────

function QuizApp(mountId) {
  const mount = document.getElementById(mountId);
  if (!mount) return;

  const form = el("form", {
    className: "quiz-form",
    id: "quiz-form",
    noValidate: true,
  });
  form.setAttribute("aria-label", "Computer Languages Quiz");

  // Build question cards
  const cards = QUESTIONS.map((q) => {
    const card = QuestionCard(q);
    form.appendChild(card.fieldset);
    return card;
  });

  // Score banner
  const scoreBanner = ScoreBanner();
  form.appendChild(scoreBanner.banner);

  // Actions
  const actions = el("div", { className: "quiz-actions" });

  const submitBtn = el("button", {
    type: "submit",
    className: "btn-submit",
    id: "submit-btn",
  });
  submitBtn.innerHTML = `<svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="2 8 6 12 14 4"/></svg> Submit answers`;

  const retryBtn = el("button", {
    type: "button",
    className: "btn-retry",
    id: "retry-btn",
    hidden: true,
  });
  retryBtn.innerHTML = `<svg width="15" height="15" viewBox="0 0 16 16" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="1 4 1 10 7 10"/><path d="M1 10 A7 7 0 1 1 3.5 3.5"/></svg> Try again`;

  actions.appendChild(submitBtn);
  actions.appendChild(retryBtn);
  form.appendChild(actions);

  // Live region for screen-reader announcements
  const liveRegion = el("div", {
    className: "sr-only",
    ariaLive: "assertive",
    ariaAtomic: "true",
    id: "live-region",
  });
  form.appendChild(liveRegion);

  mount.appendChild(form);

  // ── Event handlers ──

  form.addEventListener("submit", (e) => {
    e.preventDefault();

    let totalCorrect = 0;
    cards.forEach((card) => {
      card.applyResults();
      totalCorrect += card.score();
    });

    form.classList.add("quiz-form--submitted");
    submitBtn.disabled = true;
    submitBtn.hidden = true;
    retryBtn.hidden = false;

    scoreBanner.show(totalCorrect, QUESTIONS.length);

    // Announce to screen readers
    liveRegion.textContent = `Quiz submitted. You scored ${totalCorrect} out of ${QUESTIONS.length}.`;

    // Move focus to score banner
    scoreBanner.banner.setAttribute("tabindex", "-1");
    scoreBanner.banner.focus();
  });

  retryBtn.addEventListener("click", () => {
    // Reset form state
    form.reset();
    form.classList.remove("quiz-form--submitted");

    // Clear result classes and re-enable inputs
    cards.forEach(({ fieldset }) => {
      fieldset.querySelectorAll(".option").forEach((opt) => {
        opt.classList.remove("option--correct", "option--incorrect", "option--missed");
      });
      fieldset.querySelectorAll("input").forEach((inp) => {
        inp.disabled = false;
      });
      fieldset.querySelectorAll(".option__badge").forEach((b) => {
        b.textContent = "";
      });
    });

    // Reset score banner
    scoreBanner.banner.setAttribute("aria-hidden", "true");
    liveRegion.textContent = "";

    submitBtn.disabled = false;
    submitBtn.hidden = false;
    retryBtn.hidden = true;

    // Move focus to first question
    const firstLegend = form.querySelector("legend");
    if (firstLegend) {
      form.querySelector(".form-field").setAttribute("tabindex", "-1");
      form.querySelector(".form-field").focus();
      form.querySelector(".form-field").removeAttribute("tabindex");
    }
  });
}

