// ── OptionItem component ──────────────────────────────────────────────────────

function OptionItem({ questionId, option, name }) {
  const wrapper = el("li", { className: "option", id: `opt-${option.id}` });

  const input = el("input", {
    type: "checkbox",
    className: "option__input",
    id: option.id,
    name,
    value: option.id,
  });

  const box = el("span", { className: "option__box" });
